import java.util.*;
/** Transaction-equivalent test store; production uses gunny_tribal in Postgres. */
final class TribalMemory {
 final CloudStore.Memory store;final Map<String,Map<String,Object>> runs=new HashMap<>(),matches=new HashMap<>(),receipts=new HashMap<>();final Random random=new java.security.SecureRandom();
 TribalMemory(CloudStore.Memory store){this.store=store;}
 @SuppressWarnings("unchecked") synchronized Map<String,Object> apply(String action,Map<String,Object> p){
  if(action.equals("status"))return Map.of();
  if(action.equals("checkpoint")){String run=Json.str(p,"run");var old=runs.get(run);if(old==null||Json.num(old,"stage",0)<Json.num(p,"stage",0)||Json.num(old,"stage",0)==Json.num(p,"stage",0)&&Json.num(old,"turn",0)<=Json.num(p,"turn",0))runs.put(run,new HashMap<>(p));return Map.of();}
  if(action.equals("wing")){var profile=store.profile(Json.str(p,"user"));boolean equip=Boolean.TRUE.equals(p.get("equip"));if(equip&&profile.wings==0)throw new IllegalArgumentException("Chưa sở hữu cánh");profile.wingEquipped=equip;return Map.of("owned",profile.wings,"equipped",equip);}
  String match=Json.str(p,"match");
  if(action.equals("finish")){if(matches.containsKey(match))return Map.of();int stage=Json.num(p,"stage",0),diff=Json.num(p,"difficulty",-1);if(stage<1||stage>4||diff<0||diff>2)throw new IllegalArgumentException("Sai phó bản");var players=(List<Map<String,Object>>)p.get("players");Set<String> ids=new HashSet<>();for(var player:players){String id=Json.str(player,"id");if(!ids.add(id))throw new IllegalArgumentException("Trùng người chơi");store.profile(id);}int[] deck=new int[18];if(stage==4){List<Integer> positions=new ArrayList<>();for(int i=0;i<18;i++)positions.add(i);Collections.shuffle(positions,random);int n=0;if(diff==2)deck[positions.get(n++)]=2;for(int i=0;i<(diff==2?6:diff==1?3:0);i++)deck[positions.get(n++)]=3;}
   var row=new HashMap<>(p);row.put("deck",deck);row.put("taken",new HashSet<Integer>());row.put("ids",ids);matches.put(match,row);for(String id:ids){var profile=store.profile(id);profile.experience+=Json.num(p,"winner",-1)==0?150*(diff+1):50;if(Json.num(p,"winner",-1)==0&&stage==4)profile.giftBags=Math.min(999999,profile.giftBags+1);if(Json.num(p,"winner",-1)==0)profile.coins=Math.min(999999,profile.coins+200*(diff+1));}return Map.of();}
  if(!action.equals("claim"))throw new IllegalArgumentException("Sai thao tác");var row=matches.get(match);String id=Json.str(p,"user");int pick=Json.num(p,"pick",-1),card=Json.num(p,"card",-1);if(row==null||Json.num(row,"winner",-1)!=0||!((Set<String>)row.get("ids")).contains(id)||pick<0||pick>1||card<0||card>=18)throw new IllegalArgumentException("Không có quyền nhận thưởng");String key=match+":"+id+":"+pick;var old=receipts.get(key);if(old!=null){if(Json.num(old,"card",-1)!=card)throw new IllegalArgumentException("Reward payload mismatch");return old;}if(pick==1&&!receipts.containsKey(match+":"+id+":0"))throw new IllegalArgumentException("Chọn thẻ đầu trước");Set<Integer> taken=(Set<Integer>)row.get("taken");if(!taken.add(card))throw new IllegalArgumentException("Thẻ đã được mở");var profile=store.profile(id);int type=((int[])row.get("deck"))[card],amount=1;if(type==2){profile.wings|=1;profile.wingEquipped=true;}else if(type==3){profile.vipSpears++;profile.owned|=256;}else{int grade=StoneDrops.grade(Json.num(row,"difficulty",0),random.nextInt(100));type=StoneDrops.type(grade);int min=Json.num(row,"min",10),max=Json.num(row,"max",100);amount=min+random.nextInt(max-min+1);if(type==1)profile.stones=Math.min(999999,profile.stones+amount);else profile.craftStones[type-4]=Math.min(999999,profile.craftStones[type-4]+amount);}profile.luckyCharms++;var result=Map.<String,Object>of("card",card,"type",type,"amount",amount,"pick",pick);receipts.put(key,result);return result;
 }
}
